package com.bank.sort;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Splits rows across N partitions to mimic executors holding slices of data.
class Partitioner {
    private static final Logger log = Logger.getLogger(Partitioner.class.getName());
    private final int partitions;

    Partitioner(int partitions) { this.partitions = partitions; }

    // The 'seed' changes which rows land where, mimicking different shuffle outcomes per run.
    List<List<Trade>> partition(List<Trade> trades, int seed) {
        List<List<Trade>> buckets = new ArrayList<>();
        for (int i = 0; i < partitions; i++) buckets.add(new ArrayList<>());
        for (int i = 0; i < trades.size(); i++) {
            int target = (i + seed) % partitions;  // placement varies with seed
            buckets.get(target).add(trades.get(i));
        }
        log.fine(() -> "Partitioned " + trades.size() + " trades into " + partitions + " buckets (seed=" + seed + ")");
        return buckets;
    }
}
