package com.bank.sort;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.logging.Logger;

// Simulates Spark's non-stable distributed sort: sort each partition by amount,
// then merge in partition order. Rows with EQUAL amounts keep no original order.
class ParallelSorter {
    private static final Logger log = Logger.getLogger(ParallelSorter.class.getName());

    List<Trade> sortByAmount(List<List<Trade>> partitions) {
        // Local sort by amount ONLY (no tie-breaker) — ties resolved arbitrarily per partition.
        for (List<Trade> part : partitions) {
            part.sort(Comparator.comparing(t -> t.amount));
        }
        // Merge: concatenate partitions, then a final merge by amount only (unstable on ties).
        List<Trade> merged = new ArrayList<>();
        for (List<Trade> part : partitions) merged.addAll(part);
        merged.sort(Comparator.comparing(t -> t.amount)); // Java sort is stable, but input order
                                                           // varies by partitioning → ties vary
        log.warning(() -> "Parallel sort done (NO tie-breaker) — order of equal amounts is NOT guaranteed");
        return merged;
    }
}
