package com.bank.sort;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.concurrent.atomic.AtomicLong;
import java.util.logging.Logger;

// Deterministic sort: include a UNIQUE tie-breaker so no two rows are equal on the full key.
class StableSorter {
    private static final Logger log = Logger.getLogger(StableSorter.class.getName());

    // Uses the natural trade_seq as tie-breaker (preferred when available).
    List<Trade> sortByAmountThenSeq(List<List<Trade>> partitions) {
        List<Trade> all = flatten(partitions);
        all.sort(Comparator.comparing((Trade t) -> t.amount).thenComparingLong(t -> t.tradeSeq));
        log.info(() -> "Stable sort by (amount, trade_seq) — deterministic order on ties");
        return all;
    }

    // Simulates monotonically_increasing_id(): assign ids per partition, then sort by (amount, id).
    List<Trade> sortByAmountThenMonotonicId(List<List<Trade>> partitions) {
        AtomicLong base = new AtomicLong(0);
        for (List<Trade> part : partitions) {
            // Spark reserves a high range per partition; we emulate with partition offset.
            long partitionBase = base.getAndAdd(1_000_000L);
            long idx = 0;
            for (Trade t : part) t.monotonicId = partitionBase + (idx++);
        }
        List<Trade> all = flatten(partitions);
        all.sort(Comparator.comparing((Trade t) -> t.amount).thenComparingLong(t -> t.monotonicId));
        log.info(() -> "Stable sort by (amount, monotonic_id) — deterministic, repeatable order");
        return all;
    }

    private List<Trade> flatten(List<List<Trade>> partitions) {
        List<Trade> all = new ArrayList<>();
        for (List<Trade> part : partitions) all.addAll(part);
        return all;
    }
}
