package com.bank.sort;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

public class SortStabilityDemo {
    private static final Logger log = Logger.getLogger(SortStabilityDemo.class.getName());

    public static void main(String[] args) {
        List<Trade> trades = new ArrayList<>();
        // Several trades share the amount 50000 — these are the tie rows we watch.
        trades.add(new Trade("TRD-1", "SAV2001", new BigDecimal("50000"), 1));
        trades.add(new Trade("TRD-2", "CUR3001", new BigDecimal("50000"), 2));
        trades.add(new Trade("TRD-3", "SAV2001", new BigDecimal("50000"), 3));
        trades.add(new Trade("TRD-4", "CUR3001", new BigDecimal("30000"), 4));
        trades.add(new Trade("TRD-5", "SAV2001", new BigDecimal("70000"), 5));

        Partitioner partitioner = new Partitioner(4);
        ParallelSorter unstable = new ParallelSorter();
        StableSorter stable = new StableSorter();

        // UNSTABLE: two runs with different shuffle seeds → representative for 50000 can change.
        Trade repRun1 = firstFor(unstable.sortByAmount(partitioner.partition(trades, 0)), "50000");
        Trade repRun2 = firstFor(unstable.sortByAmount(partitioner.partition(trades, 2)), "50000");
        log.warning(() -> "UNSTABLE representative for Rs.50000 — run1=" + repRun1 + "  run2=" + repRun2
                + "  same? " + repRun1.tradeId.equals(repRun2.tradeId));

        // STABLE: two runs with different seeds → representative is identical.
        Trade sRun1 = firstFor(stable.sortByAmountThenSeq(partitioner.partition(trades, 0)), "50000");
        Trade sRun2 = firstFor(stable.sortByAmountThenSeq(partitioner.partition(trades, 2)), "50000");
        log.info(() -> "STABLE representative for Rs.50000 — run1=" + sRun1 + "  run2=" + sRun2
                + "  same? " + sRun1.tradeId.equals(sRun2.tradeId));
    }

    // Picks the first trade for a given amount — the "representative" row.
    private static Trade firstFor(List<Trade> sorted, String amount) {
        BigDecimal target = new BigDecimal(amount);
        for (Trade t : sorted) if (t.amount.compareTo(target) == 0) return t;
        return null;
    }
}
